package agent

import (
	"context"
	"fmt"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[types.AgentName]Factory)
)

// Factory creates a new agent instance
type Factory func() Agent

// Register adds an agent factory to the registry.
// Called from init() in each agent implementation.
func Register(name types.AgentName, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// Get retrieves an agent by name.
//

func Get(name types.AgentName) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown agent: %s (available: %v)", name, ListAll())
	}
	return factory(), nil
}

// List returns all registered agent names in sorted order.
func ListAll() []types.AgentName {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]types.AgentName, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// ResolvedAgent pairs an agent with the registry name it is addressed by.
// The registry name — not Agent.Name() — is the identity users type and
// Get accepts; an external plugin's self-reported name can differ from the
// name derived from its binary, which is what it is registered under.
type ResolvedAgent struct {
	Name  types.AgentName
	Agent Agent
}

// ListResolved returns the resolved, user-facing agents in sorted name order:
// every registered agent except the test-only ones. It is the single place the
// test-only filter is applied, so callers that need the Agent value (to check
// hook support or externality) get the same answer as callers that only need
// names via StringList.
//
// Agents that vanish from the registry between listing and resolving (a
// concurrent restore of a testing snapshot is the only way that happens) are
// skipped.
func ListAvailable() []ResolvedAgent {
	names := ListAll()
	agents := make([]ResolvedAgent, 0, len(names))
	for _, name := range names {
		ag, err := Get(name)
		if err != nil {
			continue
		}
		if to, ok := ag.(TestOnly); ok && to.IsTestOnly() {
			continue
		}
		agents = append(agents, ResolvedAgent{Name: name, Agent: ag})
	}
	return agents
}

// StringList returns user-facing agent names, excluding test-only agents.
func AvailableNames() []string {
	resolved := ListAvailable()
	names := make([]string, 0, len(resolved))
	for _, ra := range resolved {
		names = append(names, string(ra.Name))
	}
	return names
}

// DetectAll returns all agents whose DetectPresence reports true.
// Agents are checked in sorted name order (via ListAll()) for deterministic results.
// Returns an empty slice when no agent is detected.
func DetectAll(ctx context.Context) []Agent {
	names := ListAll() // sorted, lock-safe

	var detected []Agent
	for _, name := range names {
		ag, err := Get(name)
		if err != nil {
			continue
		}
		if present, err := ag.DetectPresence(ctx); err == nil && present {
			detected = append(detected, ag)
		}
	}
	return detected
}

// AgentForTranscriptPath returns the registered agent whose session directory
// for repoPath contains the given transcript path. Used to disambiguate which
// agent owns a session when multiple agents' hooks fire for the same session
// ID — a Cursor transcript path uniquely identifies a Cursor session even
// when Claude Code's hook is the one firing.
